PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS publishers (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, city TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, parent_id TEXT REFERENCES categories(id), color TEXT, description TEXT);
CREATE TABLE IF NOT EXISTS shelves (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, room TEXT, floor TEXT, section TEXT, capacity INTEGER, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS books (id TEXT PRIMARY KEY, isbn10 TEXT, isbn13 TEXT, title TEXT NOT NULL, subtitle TEXT, description TEXT, language TEXT NOT NULL DEFAULT 'English', publication_year INTEGER, publication_date TEXT, edition TEXT, page_count INTEGER, cover_path TEXT, cover_url TEXT, publisher_id TEXT REFERENCES publishers(id), category_id TEXT REFERENCES categories(id), call_number TEXT, dewey_code TEXT, notes TEXT, source TEXT NOT NULL DEFAULT 'manual', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE IF NOT EXISTS authors (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, biography TEXT, external_ids TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS book_authors (book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES authors(id), author_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(book_id, author_id));
CREATE TABLE IF NOT EXISTS copies (id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), accession_number TEXT NOT NULL UNIQUE, barcode TEXT NOT NULL UNIQUE, shelf_id TEXT REFERENCES shelves(id), acquisition_date TEXT, acquisition_source TEXT, price REAL, condition TEXT NOT NULL DEFAULT 'good', status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','on-loan','reserved','repair','lost','archived')), notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, member_number TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, email TEXT, phone TEXT, department TEXT, role TEXT, address TEXT, joined_at TEXT NOT NULL, expiry_date TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','expired','archived')), notes TEXT, avatar_path TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE IF NOT EXISTS loans (id TEXT PRIMARY KEY, copy_id TEXT NOT NULL REFERENCES copies(id), member_id TEXT NOT NULL REFERENCES members(id), borrowed_at TEXT NOT NULL, due_at TEXT NOT NULL, returned_at TEXT, renewed_count INTEGER NOT NULL DEFAULT 0, issued_by TEXT, received_by TEXT, condition_out TEXT, condition_in TEXT, notes TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_loan_per_copy ON loans(copy_id) WHERE returned_at IS NULL;
CREATE TABLE IF NOT EXISTS reservations (id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), member_id TEXT NOT NULL REFERENCES members(id), status TEXT NOT NULL CHECK(status IN ('queued','ready','fulfilled','cancelled','expired')), position INTEGER NOT NULL, reserved_at TEXT NOT NULL, expires_at TEXT, fulfilled_at TEXT);
CREATE TABLE IF NOT EXISTS fines (id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loans(id), member_id TEXT NOT NULL REFERENCES members(id), amount REAL NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', waived_reason TEXT, paid_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tags (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, color TEXT);
CREATE TABLE IF NOT EXISTS book_tags (book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id), PRIMARY KEY(book_id,tag_id));
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id) ON DELETE CASCADE, label TEXT NOT NULL, local_path TEXT NOT NULL, mime_type TEXT, size INTEGER, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_searches (id TEXT PRIMARY KEY, name TEXT NOT NULL, query_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS integration_cache (provider TEXT NOT NULL, cache_key TEXT NOT NULL, payload_json TEXT NOT NULL, expires_at TEXT NOT NULL, PRIMARY KEY(provider, cache_key));
CREATE TABLE IF NOT EXISTS inventory_sessions (id TEXT PRIMARY KEY, name TEXT NOT NULL, shelf_id TEXT REFERENCES shelves(id), status TEXT NOT NULL CHECK(status IN ('active','paused','completed','cancelled')), started_at TEXT NOT NULL, completed_at TEXT, created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_scans (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES inventory_sessions(id) ON DELETE CASCADE, copy_id TEXT REFERENCES copies(id), scanned_barcode TEXT NOT NULL, result TEXT NOT NULL CHECK(result IN ('found','misplaced','unknown')), scanned_at TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS catalog_fts USING fts5(title, isbn, authors, content='');
